type FontKind = 'display' | 'sans' | 'mono';
const Txt: React.FC<{x: number; y: number; w?: number; size?: number; color?: string; weight?: number; align?: 'left' | 'center' | 'right'; font?: FontKind; o?: number; caps?: boolean; box?: boolean; children?: React.ReactNode}> = ({x, y, w = 600, size = 28, color, weight = 400, align = 'left', font = 'sans', o = 1, caps = false, box = false, children}) => (
  <div style={{position: 'absolute', left: box ? x : align === 'center' ? x - w / 2 : align === 'right' ? x - w : x, top: y, width: w, textAlign: align, fontFamily: F[font], fontSize: font === 'display' ? size * D.k : size, fontWeight: weight, color: color ?? C.text, opacity: o, letterSpacing: caps ? 3 : 0, textTransform: caps ? 'uppercase' : 'none', lineHeight: 1.15, whiteSpace: 'nowrap'}}>{children}</div>
);
const Box: React.FC<{x: number; y: number; w: number; h: number; color: string; o?: number; dashed?: boolean; children?: React.ReactNode}> = ({x, y, w, h, color, o = 1, dashed = false, children}) => (
  <div style={{position: 'absolute', left: x, top: y, width: w, height: h, opacity: o, boxSizing: 'border-box', borderRadius: 8, border: `3px ${dashed ? 'dashed' : 'solid'} ${color}`, background: `${color}40`}}>{children}</div>
);
const Spike: React.FC<{x: number; y: number; h: number; color: string; o?: number}> = ({x, y, h, color, o = 1}) => (
  <div style={{position: 'absolute', left: x - 3, top: y - h, width: 6, height: h, opacity: o, background: color}}>
    <div style={{position: 'absolute', left: -7, top: -9, width: 20, height: 20, borderRadius: '50%', background: color}} />
  </div>
);
const Ruler: React.FC<{x: number; y: number; w: number; lo: number; hi: number; step: number; o?: number}> = ({x, y, w, lo, hi, step, o = 1}) => {
  const ticks: number[] = [];
  for (let v = Math.ceil(lo / step) * step; v <= hi; v += step) ticks.push(v);
  return (
    <div style={{position: 'absolute', left: 0, top: 0, opacity: o}}>
      <div style={{position: 'absolute', left: x, top: y, width: w, height: 3, background: C.mute}} />
      {ticks.map((v) => {
        const px = x + ((v - lo) / (hi - lo)) * w;
        return (
          <React.Fragment key={v}>
            <div style={{position: 'absolute', left: px - 1, top: y, width: 3, height: 14, background: C.mute}} />
            <div style={{position: 'absolute', left: px - 50, top: y + 20, width: 100, textAlign: 'center', fontFamily: F.mono, fontSize: 22, color: C.dim}}>{fmt(v)}</div>
          </React.Fragment>
        );
      })}
    </div>
  );
};
const Brace: React.FC<{x1: number; x2: number; y: number; label: string; color: string; o?: number}> = ({x1, x2, y, label, color, o = 1}) => (
  <div style={{position: 'absolute', left: 0, top: 0, opacity: o}}>
    <div style={{position: 'absolute', left: x1, top: y, width: x2 - x1, height: 3, background: color}} />
    <div style={{position: 'absolute', left: x1 - 1.5, top: y - 9, width: 3, height: 21, background: color}} />
    <div style={{position: 'absolute', left: x2 - 1.5, top: y - 9, width: 3, height: 21, background: color}} />
    <Txt x={(x1 + x2) / 2} y={y + 14} w={x2 - x1 + 300} size={30} color={color} align="center" font="mono" weight={700}>{label}</Txt>
  </div>
);

